const cfg = $('Set - Checkpoint Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.run_id);

return rows.map(r => ({
  json: {
    runId: r.run_id,
    url: cfg.selfWebhookUrl,
    previousStatus: r.status,
    failedStage: r.failed_stage || null,
    attempts: r.attempts
  }
}));

const reqs = $('JS - Build Resume Requests').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ok = res.filter(r => Number(r.statusCode) >= 200 && Number(r.statusCode) < 300).length;

return [{
  json: {
    resumableRuns: reqs.length,
    resumeCallsAccepted: ok,
    resumeCallsFailed: reqs.length - ok,
    runIds: reqs.map(r => r.runId)
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const cfgIn = ref('Set - Checkpoint Config');
const body = (cfgIn.body && typeof cfgIn.body === 'object') ? cfgIn.body : {};
const demo = cfgIn.entryMode === 'manual';

const defaultOrder = {
  orderId: 'ORD-' + Date.now(),
  customer: { name: 'Asha Patel', email: 'user@example.com' },
  items: [
    { sku: 'LAP-RUG-16', qty: 2, price: 1350 },
    { sku: 'DOCK-USB-C', qty: 2, price: 120 }
  ],
  currency: 'USD'
};

const runId = body.runId ? String(body.runId) : 'RUN-' + Date.now();
const request = {
  order: (body.order && typeof body.order === 'object') ? body.order : defaultOrder,
  // The manual demo injects one failure at charge_payment so the resume path is visible.
  failAt: body.failAt !== undefined ? String(body.failAt) : (demo ? 'charge_payment' : ''),
  failTimes: Number(body.failTimes) || 1
};

const config = {
  workflowName: cfgIn.workflowName,
  maxStageAttempts: Math.max(1, Number(cfgIn.maxStageAttempts) || 2),
  stageBackoffSeconds: Math.max(1, Number(cfgIn.stageBackoffSeconds) || 3),
  maxBackoffSeconds: Math.max(1, Number(cfgIn.maxBackoffSeconds) || 30),
  maxRunAttempts: Math.max(1, Number(cfgIn.maxRunAttempts) || 3),
  resumeDelayMinutes: Math.max(1, Number(cfgIn.resumeDelayMinutes) || 5),
  leaseMinutes: Math.max(1, Number(cfgIn.leaseMinutes) || 10),
  slackChannel: cfgIn.slackChannel
};

return [{ json: { runId, resumeRequested: !!body.runId, entryMode: cfgIn.entryMode, request, config, startedAt: Date.now() } }];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const init = ref('JS - Init Run');
const row = $input.first().json;
const exists = !!(row && row.run_id);

const STAGES = ['validate_order', 'reserve_inventory', 'charge_payment', 'create_shipment', 'send_confirmation'];

// A resumed run always reuses the payload stored when it first started.
const request = (exists && row.payload && typeof row.payload === 'object') ? row.payload : init.request;

let cps = row.checkpoints;
if (typeof cps === 'string') { try { cps = JSON.parse(cps); } catch (e) { cps = []; } }
if (!Array.isArray(cps)) cps = [];
const byStage = {};
cps.forEach(c => { byStage[c.stage] = c; });

// Resume point = first stage without a completed checkpoint (contiguous prefix only).
let stageIndex = 0;
const context = {};
const completedStages = [];
while (stageIndex < STAGES.length && byStage[STAGES[stageIndex]]) {
  context[STAGES[stageIndex]] = byStage[STAGES[stageIndex]].output;
  completedStages.push(STAGES[stageIndex]);
  stageIndex++;
}

const alreadyCompleted = exists && row.status === 'completed';
const resumed = exists && (stageIndex > 0 || ['failed', 'running', 'dead_letter'].includes(row.status));

return [{
  json: {
    runId: init.runId,
    request,
    config: init.config,
    stages: STAGES,
    stageIndex,
    completedStages,
    context,
    stageAttempt: 0,
    stageHistory: [],
    runAttempt: (Number(row.attempts) || 0) + 1,
    startedAt: init.startedAt,
    alreadyCompleted,
    resumeInfo: {
      resumed,
      previousStatus: exists ? row.status : 'new',
      previousFailedStage: row.failed_stage || null,
      previousError: row.last_error || null,
      resumedFromStage: STAGES[stageIndex] || null,
      skippedStages: completedStages,
      note: (init.resumeRequested && !exists) ? 'runId not found: started as a new run' : ''
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const lock = $input.first().json;
const plan = ref('JS - Build Execution Plan');

// The Postgres node replaced the item with the lock row, so restore the plan.
return [{
  json: {
    ...plan,
    runAttempt: Number(lock.attempts) || plan.runAttempt,
    lockAcquiredAt: Date.now()
  }
}];

const s = $input.first().json;
const stage = s.stages[s.stageIndex] || null;

return [{
  json: {
    ...s,
    stage,
    allDone: !stage,
    stageAttempt: s.stageAttempt + 1,
    stageStartedAt: Date.now(),
    idempotencyKey: s.runId + ':' + stage
  }
}];

const s = $input.first().json;
function h(str) { let x = 0; for (let i = 0; i < str.length; i++) { x = (Math.imul(31, x) + str.charCodeAt(i)) | 0; } return Math.abs(x).toString(36).toUpperCase(); }
function maybeFail(stage) {
  if (s.request.failAt === stage && s.runAttempt <= (Number(s.request.failTimes) || 1)) {
    throw new Error('Injected failure at ' + stage + ' (run attempt ' + s.runAttempt + ')');
  }
}
const fail = (error, retryable = true) => [{ json: { ...s, stageResult: { ok: false, retryable, error } } }];
const ok = (output) => [{ json: { ...s, stageResult: { ok: true, output } } }];
const order = s.request.order || {};
const ctx = s.context || {};

// Replace with your real step (HTTP / DB / etc.). Use s.idempotencyKey for any external side effect.
try {
  maybeFail('validate_order');
  if (!Array.isArray(order.items) || order.items.length === 0) {
    return fail('Order has no items (permanent validation error)', false);
  }
  const total = order.items.reduce((sum, i) => sum + Number(i.qty) * Number(i.price), 0);
  return ok({ valid: true, itemCount: order.items.length, total, currency: order.currency || 'USD' });
} catch (e) { return fail(e.message); }

