function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const s = ref('JS - Select Stage');
const r = $input.first().json;

let ok = false, output = null, error = null, retryable = true;
if (r.stageResult) {
  ok = r.stageResult.ok === true;
  output = r.stageResult.output || null;
  error = r.stageResult.error || null;
  retryable = r.stageResult.retryable !== false;
} else if (r.error) {
  // A stage node threw and continueOnFail turned the error into data.
  error = typeof r.error === 'string' ? r.error : (r.error.message || 'Stage node error');
} else {
  error = 'Stage returned no result';
}

return [{
  json: {
    ...s,
    stageOk: ok,
    stageOutput: output,
    stageError: error,
    stageRetryable: retryable,
    stageDurationMs: Date.now() - s.stageStartedAt
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
// The Postgres node replaced the item, so restore the state captured before the checkpoint write.
const s = ref('JS - Capture Stage Result');

return [{
  json: {
    ...s,
    context: { ...s.context, [s.stage]: s.stageOutput },
    completedStages: [...s.completedStages, s.stage],
    stageHistory: [...s.stageHistory, { stage: s.stage, attempts: s.stageAttempt, durationMs: s.stageDurationMs, ok: true }],
    stageIndex: s.stageIndex + 1,
    stageAttempt: 0,
    stageError: null
  }
}];

const s = $input.first().json;
const cfg = s.config;

const retryStage = s.stageRetryable && s.stageAttempt < cfg.maxStageAttempts;
let backoffSeconds = 0;
if (retryStage) {
  const exp = cfg.stageBackoffSeconds * Math.pow(2, s.stageAttempt - 1);
  const jitter = Math.random() * cfg.stageBackoffSeconds;
  backoffSeconds = Math.round(Math.min(cfg.maxBackoffSeconds, exp + jitter) * 10) / 10;
}

return [{
  json: {
    ...s,
    retryStage,
    backoffSeconds,
    permanentFailure: !s.stageRetryable,
    stageHistory: [...s.stageHistory, { stage: s.stage, attempts: s.stageAttempt, durationMs: s.stageDurationMs, ok: false, error: s.stageError }]
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const s = ref('JS - Plan Stage Retry');
const row = $input.first().json;

return [{
  json: {
    runId: s.runId,
    failedStage: s.stage,
    error: s.stageError,
    permanent: s.permanentFailure,
    runStatus: row.status || 'failed',
    runAttempts: row.attempts !== undefined ? row.attempts : s.runAttempt,
    nextRetryAt: row.next_retry_at || null,
    completedStages: s.completedStages,
    config: s.config
  }
}];

