function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const s = ref('JS - Select Stage');
const row = $input.first().json;

const executed = s.stageHistory.filter(h => h.ok).map(h => h.stage);
return [{
  json: {
    runId: s.runId,
    outcome: 'completed',
    recovered: s.resumeInfo.resumed === true,
    resumedFromStage: s.resumeInfo.resumedFromStage,
    previousFailedStage: s.resumeInfo.previousFailedStage,
    previousError: s.resumeInfo.previousError,
    skippedStages: s.resumeInfo.skippedStages,
    executedStages: executed,
    runAttempts: row.attempts !== undefined ? row.attempts : s.runAttempt,
    results: s.context,
    totalDurationMs: Date.now() - s.startedAt,
    config: s.config
  }
}];

